class EduStaffApp extends StatefulWidget {
  const EduStaffApp({super.key});
  @override State<EduStaffApp> createState() => _EduStaffAppState();
}

class _EduStaffAppState extends State<EduStaffApp> {
  final api = ApiService();
  Map<String, dynamic>? user;
  bool loading = true;
  String error = '';
  @override void initState() { super.initState(); restore(); }
  Future<void> restore() async {
    try { if ((await api.readToken())?.isNotEmpty == true) user = Map<String, dynamic>.from(await api.request('GET', '/auth/me')); }
    catch (e) { await api.clearToken(); error = '$e'; }
    finally { if (mounted) setState(() => loading = false); }
  }
  void signedIn(Map<String, dynamic> value) => setState(() { user = value; error = ''; });
  Future<void> logout() async { try { await api.request('POST', '/auth/logout'); } catch (_) {} await api.clearToken(); if (mounted) setState(() => user = null); }
  @override Widget build(BuildContext context) => MaterialApp(
    title: 'EduStaff', debugShowCheckedModeBanner: false,
    theme: ThemeData(useMaterial3: true, colorScheme: ColorScheme.fromSeed(seedColor: blue, primary: blue), scaffoldBackgroundColor: const Color(0xFFEAF2FF), fontFamily: 'Roboto', inputDecorationTheme: InputDecorationTheme(filled: true, fillColor: const Color(0xFFFBFDFF), contentPadding: const EdgeInsets.symmetric(horizontal: 13, vertical: 12), hintStyle: const TextStyle(color: Color(0xFF94A3B8)), border: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: const BorderSide(color: border)), enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: const BorderSide(color: border)), focusedBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: const BorderSide(color: blue, width: 1.5)))),
    home: loading ? const Scaffold(body: Center(child: CircularProgressIndicator(color: blue))) : user == null ? LoginPage(api: api, initialError: error, onSuccess: signedIn) : AppShell(api: api, user: user!, onLogout: logout),
  );
}

