Future<void> openPhoneApp(String phone,{required bool message}) async {
  final cleaned = phone.trim();
  if (cleaned.isEmpty) return;
  final uri = Uri(scheme: message ? 'sms' : 'tel', path: cleaned);
  await launchUrl(uri, mode: LaunchMode.externalApplication);
}

