Map<String,dynamic> asMap(dynamic x)=>x is Map<String,dynamic>?x:x is Map?Map<String,dynamic>.from(x):<String,dynamic>{};
String initial(dynamic x){final s='$x'.trim();return s.isEmpty?'E':s.substring(0,1).toUpperCase();}
String titleCase(String s)=>s.replaceAll('-',' ').split(' ').map((x)=>x.isEmpty?x:'${x[0].toUpperCase()}${x.substring(1)}').join(' ');
String dateText(dynamic x){if(x==null)return '—';final d=DateTime.tryParse('$x');return d==null?'$x':'${d.day}/${d.month}/${d.year}';}
String dateOnly(dynamic x){if(x==null)return '—';final d=DateTime.tryParse('$x');return d==null?'$x':'${d.month}/${d.day}/${d.year}';}
void toast(BuildContext c,Object e)=>ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('$e')));
Future<bool> confirmBox(BuildContext c,String title,String message)async=>await showDialog<bool>(context:c,builder:(_)=>AlertDialog(title:Text(title),content:Text(message),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Confirm'))]))??false;
